// Class presentations: one deck per session, 25–30 slides each, every slide with speaker notes (n).
// Slide types: cover, section, points, cards, flow, compare, statement, discuss, scenario, check, reflect.
// check: q = question, o = options, a = index of the strongest option, why = explanation shown after answering.
import { lessons } from './lessons.js';

const L = id => lessons.find(l => l.id === id);

// Shared slides built from the lesson record, so the plan, quiz and slides never disagree.
const cover = id => ({ t: 'cover', n: `Welcome the group to session ${L(id).n}. Read the title, then give the purpose in your own words: ${L(id).intro} Say how long the session runs (${L(id).minutes} minutes) and that there is a practical activity in the middle.` });
const outcomes = id => ({ t: 'points', k: 'Outcomes', h: 'By the end of this session you can', items: L(id).outcomes, n: 'Read the three outcomes aloud. Ask people to pick the one that matters most in their job right now and keep it in mind; you will come back to it in the reflection.' });
const activity = id => ({ t: 'points', k: 'Group practice', h: L(id).activity, items: L(id).instructions, n: 'Brief the whole activity before anyone moves. Check that every group knows the task, the time limit and what they will report back. Then circulate and listen for examples you can use in the debrief.' });
const lessonCheck = id => ({ t: 'check', q: L(id).scenario, o: L(id).choices, a: L(id).correct, why: L(id).reason, n: 'Let the room call out an answer and say why before you tap it. If people disagree, ask each side for their reasoning first: the discussion matters more than the answer.' });
const reflect = id => ({ t: 'reflect', h: 'Apply it at work', p: L(id).prompt, n: 'Give two minutes of quiet writing. Participants can type their answer in the Notes tab; it is private to them. Invite one or two volunteers to share, but do not push anyone.' });

